export function runtimeBundle({browser,pixel,interaction,rollback}={}){const checks={browser:browser?.status==="PASS"&&browser.real===true,pixel:pixel?.status==="PASS"&&pixel.real===true,interaction:interaction?.status==="PASS"&&interaction.real===true,rollback:rollback===true};const failed=Object.entries(checks).filter(([,v])=>!v).map(([k])=>k);return{status:failed.length?"BLOCKED":"PASS",failed,real:failed.length===0,publish_candidate:failed.length===0}}